// Alert only when the cheapest fare is at or under this price.
const THRESHOLD = 450;
const flights = $input.all().map((i) => i.json).filter((f) => typeof f.price === 'number');
if (!flights.length) return [];
const c = flights.reduce((a, b) => (b.price < a.price ? b : a));
if (c.price > THRESHOLD) return [];
const stops = c.stops === 0 ? 'nonstop' : `${c.stops} stop${c.stops > 1 ? 's' : ''}`;
const date = c.departureDate || String(c.departure || '').slice(0, 10);
const dates = c.returnDate ? `${date} to ${c.returnDate} (round trip)` : date;
return [{ json: { message: `✈️ ${c.from} → ${c.to}, ${dates}: ${c.currency} ${c.price} with ${(c.airlines || []).join(', ')} (${stops}, ${c.duration}). ${c.googleFlightsUrl || ''}` } }];
